import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

// ⚠️ GEMINI API KEY BURAYA GELECEK
const GEMINI_API_KEY = ""; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [seciliMekanId, setSeciliMekanId] = useState(null);
  const [veriYukleniyor, setVeriYukleniyor] = useState(true);
  const [muzekartVar, setMuzekartVar] = useState(false);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => {
        setMekanlar(data);
        setVeriYukleniyor(false);
      })
      .catch(err => {
        console.warn("Backend bağlantısı başarısız.", err);
        setVeriYukleniyor(false);
      });
  }, []);

  const kategoriler = {
    "Tarih": mekanlar.filter(m => m.kategori === "Tarih"),
    "Doğa": mekanlar.filter(m => m.kategori === "Doğa"),
    "Eğlence": mekanlar.filter(m => m.kategori === "Eğlence"),
    "Dalış": mekanlar.filter(m => m.kategori === "Dalış"),
    "Tekne": mekanlar.filter(m => m.kategori === "Tekne"),
    "Yemek": mekanlar.filter(m => m.kategori === "Yemek"),
  };

  const kategoriArkaPlanlari = {
    "Tarih": "https://images.unsplash.com/photo-1528164344705-475426870763?q=80&w=2070", 
    "Doğa": "https://images.unsplash.com/photo-1433838552652-f9a46b332c40?q=80&w=2070", 
    "Eğlence": "https://images.unsplash.com/photo-1566737236500-c8ac43014a67?q=80&w=2070", 
    "Dalış": "https://images.unsplash.com/photo-1544551763-46a013bb70d5?q=80&w=2070",
    "Tekne": "https://images.unsplash.com/photo-1534008897995-27a23e859048?q=80&w=2070",
    "Yemek": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?q=80&w=1974", 
  };

  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Listeniz boş!");
    const duraklar = favoriler.map(m => encodeURIComponent(m.ad)).join('/');
    window.open(`https://www.google.com/maps/dir/${duraklar}`, '_blank');
  };

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    else setFavoriler([...favoriler, mekan]);
  };

  const askSmartAI = async (mekan) => {
    if (seciliMekanId === mekan.id) { setSeciliMekanId(null); return; }
    setSeciliMekanId(mekan.id);
    setLoading(true);
    try {
      const wRes = await fetch(`http://localhost:5000/api/hava-durumu?lat=${mekan.lat}&lon=${mekan.lon}`);
      const wData = await wRes.json(); 
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      const prompt = `Antalya ${mekan.ad} konumundayım. Hava ${wData.sicaklik}°C. Kısa bir turist rehberi ipucu ver.`;
      const result = await model.generateContent(prompt);
      setAiBilgi({ cevap: result.response.text(), temp: wData.sicaklik, durum: wData.durum });
    } catch (err) {
      setAiBilgi({ cevap: "Bağlantı hatası!", temp: "--", durum: "?" });
    } finally { setLoading(false); }
  };

  if (veriYukleniyor) return <div className="loading-screen">🌘 Rotalar Yükleniyor...</div>;

  return (
    <div className="main-container">
      <style>{`
        /* --- GENEL STİLLER --- */
        body { margin: 0; background: #000; color: #e2e8f0; font-family: 'Poppins', sans-serif; }
        .navbar { display: flex; justify-content: space-between; align-items: center; padding: 15px 40px; background: rgba(0,0,0,0.9); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid rgba(255,255,255,0.1); }
        .nav-link { color: #cbd5e1; text-decoration: none; font-size: 13px; padding: 8px 20px; border: 1px solid rgba(255,255,255,0.15); border-radius: 50px; background: rgba(255,255,255,0.05); transition: 0.3s; margin-right: 10px; }
        .nav-link:hover { border-color: #f97316; background: rgba(249,115,22,0.2); box-shadow: 0 0 15px rgba(249,115,22,0.4); }

        /* --- KART VE IZGARA --- */
        .category-section { position: relative; min-height: 100vh; padding: 60px 40px; background-attachment: fixed; background-size: cover; display: flex; flex-direction: column; justify-content: center; }
        .overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.7); z-index: 1; }
        .section-content { position: relative; z-index: 2; }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; }
        .card { background: rgba(30, 41, 59, 0.9); border-radius: 20px; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); transition: 0.4s; }
        .card:hover { transform: translateY(-10px); border-color: #f97316; }

        /* --- FOOTER TASARIMI (Antalya Diving Stili) --- */
        .footer { background: #001d3d; color: white; padding: 60px 40px 20px; position: relative; overflow: hidden; }
        .footer-waves { position: absolute; top: 0; left: 0; width: 100%; overflow: hidden; line-height: 0; }
        .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr; gap: 40px; position: relative; z-index: 2; }
        .footer-logo h2 { color: #f97316; margin: 0; font-size: 28px; }
        .footer-links h3, .footer-contact h3 { color: #38bdf8; font-size: 18px; }
        .footer-links ul { list-style: none; padding: 0; }
        .footer-links li { margin-bottom: 10px; opacity: 0.8; cursor: pointer; }
        .footer-links li:hover { color: #f97316; opacity: 1; }
        .footer-stats { display: flex; justify-content: space-around; text-align: center; padding: 40px 0; border-top: 1px solid rgba(255,255,255,0.1); margin-top: 30px; }
        .footer-stats strong { display: block; font-size: 32px; color: #f97316; }
        .footer-bottom { text-align: center; border-top: 1px solid rgba(255,255,255,0.1); padding-top: 20px; font-size: 12px; opacity: 0.6; }
      `}</style>

      {/* Navbar */}
      <nav className="navbar">
        <div style={{display:'flex', alignItems:'center', gap:'10px'}}>
          <span style={{fontSize:'28px'}}>🏝️</span>
          <div>
            <div style={{fontWeight:800, color:'#38bdf8', fontSize:'18px'}}>ANTALYA</div>
            <div style={{fontWeight:400, color:'#f97316', fontSize:'11px'}}>ROTA ASİSTANI</div>
          </div>
        </div>
        <div className="nav-links">
          {Object.keys(kategoriler).map(kat => <a key={kat} href={`#${kat}`} className="nav-link">{kat}</a>)}
        </div>
        <button onClick={rotayiHaritadaGoster} style={{background:'#f97316', color:'white', border:'none', padding:'10px 20px', borderRadius:'50px', fontWeight:'bold', cursor:'pointer'}}>Rotayı Çiz 🚀</button>
      </nav>

      {/* Rota İçeriği */}
      {Object.keys(kategoriler).map(katAdi => {
        const liste = kategoriler[katAdi];
        if (liste.length === 0) return null;
        return (
          <div key={katAdi} id={katAdi} className="category-section" style={{backgroundImage: `url(${kategoriArkaPlanlari[katAdi]})`}}>
            <div className="overlay"></div>
            <div className="section-content">
              <h2 style={{borderLeft:'6px solid #f97316', paddingLeft:'20px', fontSize:'32px'}}>{katAdi} Rotaları</h2>
              <div className="grid">
                {liste.map(m => (
                  <div key={m.id} className="card">
                    <img src={m.resim} alt={m.ad} style={{width:'100%', height:'200px', objectFit:'cover'}} />
                    <div style={{padding:'20px'}}>
                      <h3>{m.ad}</h3>
                      <p style={{fontSize:'13px', color:'#94a3b8'}}>{m.aciklama}</p>
                      <button onClick={() => askSmartAI(m)} style={{width:'100%', padding:'10px', background:'#334155', color:'#38bdf8', border:'none', borderRadius:'8px', cursor:'pointer'}}>✨ AI İpucu Al</button>
                      <button onClick={() => toggleFavori(m)} style={{width:'100%', marginTop:'10px', padding:'10px', background: favoriler.some(f=>f.id===m.id) ? '#ef4444' : '#0f766e', color:'white', border:'none', borderRadius:'8px', cursor:'pointer'}}>
                        {favoriler.some(f=>f.id===m.id) ? "Listeden Çıkar" : "Rotaya Ekle +"}
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        );
      })}

      {/* 🌊 YENİ: FOOTER (Antalya Diving Tasarımı) */}
      <footer className="footer">
        <div className="footer-grid">
          <div className="footer-logo">
            <h2>Antalya Diving</h2>
            <p style={{color:'#38bdf8', fontStyle:'italic'}}>Akdeniz'in En İyi Dalış Noktalarını Keşfedin</p>
            <p style={{fontSize:'14px', opacity:0.8, marginTop:'15px'}}>
              Antalya'nın tüm koylarını, tarihi kalıntılarını ve lezzet duraklarını bir araya getiren en kapsamlı rota asistanı. 
              Staj projesi olarak geliştirilmiştir.
            </p>
          </div>
          <div className="footer-links">
            <h3>Hızlı Linkler</h3>
            <ul>
              <li>Hakkımızda</li>
              <li>Dalış Noktaları</li>
              <li>Popüler Rotalar</li>
              <li>Sıkça Sorulan Sorular</li>
            </ul>
          </div>
          <div className="footer-contact">
            <h3>İletişim</h3>
            <p>📍 Akdeniz Bulvarı No:123, Konyaaltı, Antalya</p>
            <p>📞 +90 532 000 00 00</p>
            <p>📧 info@antalyarota.com</p>
          </div>
        </div>

        <div className="footer-stats">
          <div>
            <strong>14+ Yıl</strong>
            <span>Sektör Deneyimi</span>
          </div>
          <div>
            <strong>15,000+</strong>
            <span>Mutlu Gezgin</span>
          </div>
          <div>
            <strong>50+</strong>
            <span>Aktif Rota</span>
          </div>
        </div>

        <div className="footer-bottom">
          <p>© 2026 Antalya Rota Asistanı | Murat Cam </p>
          <p>Made with ❤️ for Antalya</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
